-- Disposable PostgreSQL only. Synthetic minimal relations reproduce the exact live ACLs.
CREATE ROLE anon;
CREATE ROLE authenticated;
CREATE ROLE service_role BYPASSRLS;
GRANT USAGE, CREATE ON SCHEMA public TO authenticated;
GRANT USAGE ON SCHEMA public TO anon, service_role;
CREATE FUNCTION assert_ok(ok boolean,label text) RETURNS void LANGUAGE plpgsql AS $$ BEGIN IF ok IS DISTINCT FROM true THEN RAISE EXCEPTION 'FAIL: %',label; END IF; RAISE NOTICE 'PASS: %',label; END $$;
CREATE FUNCTION assert_denied(q text,label text) RETURNS void LANGUAGE plpgsql AS $$ BEGIN BEGIN EXECUTE q; EXCEPTION WHEN insufficient_privilege THEN RAISE NOTICE 'PASS: %',label; RETURN; END; RAISE EXCEPTION 'FAIL expected 42501: %',label; END $$;
CREATE TABLE trigger_events(relation_name text,operation text);
GRANT SELECT,INSERT ON trigger_events TO authenticated,service_role;
CREATE FUNCTION record_event() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN INSERT INTO trigger_events VALUES(TG_TABLE_NAME,TG_OP); RETURN NULL; END $$;
