CREATE OR REPLACE FUNCTION public.set_manta_size_catalog_id()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
begin
  if new.fk_manta_id is null then
    new.fk_catalog_id := null;
  else
    select m.fk_catalog_id
      into new.fk_catalog_id
    from public.mantas m
    where m.pk_manta_id = new.fk_manta_id;
  end if;

  return new;
end;
$function$
;
CREATE OR REPLACE FUNCTION public.sync_manta_size_catalog_id_from_manta()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
begin
  update public.manta_sizes
  set fk_catalog_id = new.fk_catalog_id
  where fk_manta_id = new.pk_manta_id
    and fk_catalog_id is distinct from new.fk_catalog_id;

  return new;
end;
$function$
;
CREATE TRIGGER trg_set_manta_size_catalog_id BEFORE INSERT OR UPDATE OF fk_manta_id ON public.manta_sizes FOR EACH ROW EXECUTE FUNCTION set_manta_size_catalog_id();
CREATE TRIGGER trg_sync_manta_size_catalog_id_from_manta AFTER UPDATE OF fk_catalog_id ON public.mantas FOR EACH ROW WHEN ((old.fk_catalog_id IS DISTINCT FROM new.fk_catalog_id)) EXECUTE FUNCTION sync_manta_size_catalog_id_from_manta();
CREATE TABLE acl_baseline AS SELECT c.relname,a.* FROM pg_class c CROSS JOIN LATERAL aclexplode(c.relacl) a WHERE c.relnamespace='public'::regnamespace AND c.relname IN ('biopsies','manta_sizes','photo_measurements','calibration_sessions','calibration_photos','calibration_measurements','manta_embeddings','photo_embeddings','sighting_embeddings','manta_match_results');
CREATE FUNCTION relation_shape() RETURNS jsonb LANGUAGE sql AS $$ SELECT jsonb_agg(jsonb_build_object('name',c.relname,'owner',c.relowner,'rls',c.relrowsecurity,'force',c.relforcerowsecurity,'columns',(SELECT jsonb_agg(to_jsonb(a) ORDER BY attnum) FROM pg_attribute a WHERE a.attrelid=c.oid),'triggers',(SELECT jsonb_agg(pg_get_triggerdef(t.oid) ORDER BY t.oid) FROM pg_trigger t WHERE t.tgrelid=c.oid),'constraints',(SELECT jsonb_agg(pg_get_constraintdef(k.oid) ORDER BY k.oid) FROM pg_constraint k WHERE k.conrelid=c.oid)) ORDER BY c.relname) FROM pg_class c WHERE c.relnamespace='public'::regnamespace AND c.relname IN ('biopsies','manta_sizes','photo_measurements','calibration_sessions','calibration_photos','calibration_measurements','manta_embeddings','photo_embeddings','sighting_embeddings','manta_match_results') $$;
CREATE TABLE shape_baseline AS SELECT relation_shape() value;
