SELECT assert_ok(NOT EXISTS(SELECT c.relname,a.* FROM pg_class c CROSS JOIN LATERAL aclexplode(c.relacl) a WHERE c.relname IN ('biopsies','manta_sizes','photo_measurements','calibration_sessions','calibration_photos','calibration_measurements','manta_embeddings','photo_embeddings','sighting_embeddings','manta_match_results') EXCEPT SELECT * FROM acl_baseline) AND NOT EXISTS(SELECT * FROM acl_baseline EXCEPT (SELECT c.relname,a.* FROM pg_class c CROSS JOIN LATERAL aclexplode(c.relacl) a WHERE c.relname IN ('biopsies','manta_sizes','photo_measurements','calibration_sessions','calibration_photos','calibration_measurements','manta_embeddings','photo_embeddings','sighting_embeddings','manta_match_results'))),'rollback exact full ACL restored');
