\ir ../migrations/20261017021335_remove_scientific_table_schema_privileges.sql
SELECT assert_ok(NOT has_table_privilege('authenticated','biopsies',p),'biopsies removed '||p) FROM unnest(ARRAY['TRUNCATE','REFERENCES','TRIGGER']) p;
SELECT assert_ok(has_table_privilege('authenticated','biopsies',p)=(p='SELECT'),'biopsies retained '||p) FROM unnest(ARRAY['SELECT','INSERT','UPDATE','DELETE']) p;
SELECT assert_ok(NOT has_table_privilege('anon','biopsies',p),'biopsies anon unchanged '||p) FROM unnest(ARRAY['SELECT','INSERT','UPDATE','DELETE','TRUNCATE','REFERENCES','TRIGGER']) p;
SELECT assert_ok(has_table_privilege('service_role','biopsies',p),'biopsies service unchanged '||p) FROM unnest(ARRAY['SELECT','INSERT','UPDATE','DELETE','TRUNCATE','REFERENCES','TRIGGER']) p;
SET ROLE authenticated;
SELECT assert_ok((SELECT count(*)=1 FROM biopsies),'biopsies read');
SELECT assert_denied('TRUNCATE biopsies','biopsies truncate');
SELECT assert_denied('CREATE TABLE reference_probe(id integer REFERENCES biopsies(id))','biopsies references');
SELECT assert_denied('CREATE TRIGGER forbidden AFTER INSERT ON biopsies FOR EACH ROW EXECUTE FUNCTION record_event()','biopsies trigger creation');
RESET ROLE;
SELECT assert_ok((SELECT count(*)=1 AND min(note)='baseline' FROM biopsies),'biopsies content unchanged');
